INSERT INTO `wp_options` VALUES (562,'_elementor_notifications_data','a:2:{s:7:\"timeout\";i:1788000025;s:5:\"value\";s:3248:\"[{\"id\":\"webinar-cinematic-scroll-mcp-rewatch\",\"title\":\"Webinar rewatch: Cinematic scroll & MCP teaser\",\"description\":\"See how to generate a full page from simple prompts, add an immersive cinematic scroll experience to your site and get a first look at the Elementor MCP that\'s coming soon.\",\"topic\":\"Webinar\",\"imageSrc\":\"https:\\/\\/assets.elementor.com\\/notifications\\/v1\\/images\\/webinar-cinematic-scroll-mcp.png\",\"chipTags\":[\"Webinar\"],\"link\":\"https:\\/\\/www.youtube.com\\/watch?v=qyr0VGwpA8I\",\"readMoreText\":\"Learn more\"},{\"id\":\"angie-build-full-page\",\"title\":\"Generate full Elementor pages\",\"description\":\"Describe the layout you need and get a complete page, or generate individual sections like hero areas, feature blocks, and pricing tables one at a time. Every result can be matched to your site\'s existing styles or follow any new design instructions you give.\",\"topic\":\"Angie\",\"imageSrc\":\"https:\\/\\/assets.elementor.com\\/notifications\\/v1\\/images\\/angie-build-full-page.png\",\"chipTags\":[\"Angie\"],\"link\":\"https:\\/\\/go.elementor.com\\/go-pro-notification-angie-build-with-prompts\\/\",\"readMoreText\":\"Learn More\"},{\"id\":\"angie-build-design-system\",\"title\":\"Turn a screenshot into a design system\",\"description\":\"Describe your site\'s look, upload a screenshot, or paste your values, and get a base design system built automatically: colors and typography as reusable variables and classes or global styles. Every layout Angie builds draws from the same system, so new pages stay consistent.\",\"topic\":\"Angie\",\"imageSrc\":\"https:\\/\\/assets.elementor.com\\/notifications\\/v1\\/images\\/angie-build-design-system.png\",\"chipTags\":[\"Angie\"],\"link\":\"https:\\/\\/go.elementor.com\\/go-pro-notification-angie-build-with-prompts\\/\",\"readMoreText\":\"Learn More\"},{\"id\":\"angie-super-community\",\"title\":\"Angie Community Library\",\"description\":\"Browse a library of snippets and widgets built by other Angie users, import any of them into your site, without consuming any credits or remix them with a prompt to match your brief. Every snippet is vetted by the Elementor team. You can also submit your own work for the community to discover.\",\"topic\":\"Angie\",\"imageSrc\":\"https:\\/\\/assets.elementor.com\\/notifications\\/v1\\/images\\/angie-community.png\",\"chipTags\":[\"Angie\"],\"link\":\"https:\\/\\/go.elementor.com\\/go-pro-notification-angie-community\\/\",\"readMoreText\":\"Browse library\"},{\"id\":\"angie-super-admin\",\"title\":\"Super Admin Mode\",\"description\":\"Revolutionize your WordPress workflow with Super Admin Mode. Perform root-level WordPress operations through natural language - bulk post and product updates, PHP error diagnosis, and more.\",\"topic\":\"Angie\",\"imageSrc\":\"https:\\/\\/assets.elementor.com\\/notifications\\/v1\\/images\\/angie-super-admin.png\",\"chipTags\":[\"Angie\"],\"link\":\"https:\\/\\/go.elementor.com\\/go-pro-notification-angie-super-admin\\/\",\"readMoreText\":\"Learn More\"},{\"id\":\"one-launch\",\"title\":\"Introducing Elementor One\",\"description\":\"The complete website building experience. All the tools to create, optimize, and manage websites, unified under one roof.\",\"imageSrc\":\"https:\\/\\/assets.elementor.com\\/notifications\\/v1\\/images\\/one-launch.png\",\"chipTags\":[\"New Launch\"],\"cta\":\"Explore Elementor One\",\"ctaLink\":\"https:\\/\\/go.elementor.com\\/launch-whats-new\"}]\";}','off');
